const DR:[i32;8]=[1,-1,1,-1,2,2,-2,-2];const DC:[i32;8]=[2,2,-2,-2,1,-1,1,-1];
fn search(b:&mut [i32;25],n:i32,r:i32,c:i32,step:i32)->bool{if step==n*n{return true}for k in 0..8{let nr=r+DR[k];let nc=c+DC[k];if nr>=0&&nr<n&&nc>=0&&nc<n{let at=(nr*n+nc)as usize;if b[at]==0{b[at]=step+1;if search(b,n,nr,nc,step+1){return true}b[at]=0}}}false}
#[no_mangle]
pub unsafe extern "C" fn open_knight_tour(v:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if v.is_null()||n!=1||(*v!=1&&*v!=5){return -1}let d=*v as i32;let bytes=(d*d*4)as usize;if out.is_null()||cap<bytes{return -2}let mut b=[0i32;25];'starts:for r in 0..d{for c in 0..d{b[(r*d+c)as usize]=1;if search(&mut b,d,r,c,1){break 'starts}b[(r*d+c)as usize]=0}}for i in 0..(d*d)as usize{for k in 0..4{*out.add(i*4+k)=((b[i]as u32)>>(8*k))as u8}}bytes as i64}
